type lookupBlock64 struct {
	lo uint64
	hi uint64
}

var (
	lsEncLookup64 [16][256]lookupBlock64
	lInvLookup64  [16][256]lookupBlock64
	slDecLookup64 [16][256]lookupBlock64
)

// Умножение в GF(2^8) с P(x)=x^8+x^7+x^6+x+1.
// Используется в преобразовании L.
func gf2Mul(x, y uint8) uint8 {
	var z uint8
	z = 0
	for y != 0 {
		if y&1 == 1 {
			z = z ^ x
		}
		if x&0x80 != 0 {
			x = (x << 1) ^ 0xC3
		} else {
			x = x << 1
		}
		y = y >> 1
	}
	return z
}

// linear применяет L-преобразование к 128-битному блоку.
func linear(block [16]uint8) [16]uint8 {
	var i, j int
	var x uint8

	for j = 0; j < 16; j++ { // 16 раундов преобразования R (LFSR).
		// Один раунд R.
		x = block[15]
		for i = 14; i >= 0; i-- {
			block[i+1] = block[i]
			// Умножение и сложение в GF.
			x = x ^ gf2Mul(block[i], lVector[i])
		}
		block[0] = x
	}
	return block
}

// linearInv применяет обратное L-преобразование.
func linearInv(block [16]uint8) [16]uint8 {
	var i, j int
	var x uint8

	for j = 0; j < 16; j++ {
		x = block[0]
		for i = 0; i < 15; i++ {
			block[i] = block[i+1]
			x = x ^ gf2Mul(block[i], lVector[i])
		}
		block[15] = x
	}

	return block
}

func stretchKey(key [32]uint8) [10][16]uint8 {
	var x, y, z [16]uint8
	var rkeys [10][16]uint8

	// Сначала разделяем ключ на пару подключей (K_1 = x, K_2 = y).
	for i := 0; i < 16; i++ {
		x[i] = key[i]
		y[i] = key[i+16]
	}

	rkeys[0] = x
	rkeys[1] = y

	for i := 0; i < 32; i++ {
		z = x
		xorBlockInPlace(&z, cBlk[i])
		lookupTableBlock64(&z, &z, &lsEncLookup64)
		xorBlockInPlace(&z, &y)
		y = x
		x = z
		if (i+1)%8 == 0 { // Сохраняем каждую пару раундовых ключей.
			rkeys[((i + 1) >> 2)] = x
			rkeys[((i+1)>>2)+1] = y
		}
	}

	return rkeys
}

func decryptRoundKeys(rkeys [10][16]uint8) [10][16]uint8 {
	var rkeys_L [10][16]uint8

	// Вычисляем обратное L-преобразование для 9 раундовых ключей K_2..K_10.
	for k := 1; k < 10; k++ {
		lookupTableBlock64(&rkeys_L[k], &rkeys[k], &lInvLookup64)
	}
	rkeys_L[0] = rkeys[0]
	return rkeys_L
}

// CMXORKeyStream дописывает в dst результат XOR входа src с гаммой Кузнечика
// в простом counter mode. При достаточном cap(dst) функция не выделяет память.
func CMXORKeyStream(dst []byte, iv uint64, key [32]byte, src []byte) []byte {
	if len(src) == 0 {
		return dst
	}

	initCipherTables()
	rkeys := stretchKey(key)
	return cmXORKeyStream(dst, iv, &rkeys, src)
}

func cmXORKeyStream(dst []byte, iv uint64, rkeys *[10][16]byte, src []byte) []byte {
	oldLen := len(dst)
	dst = append(dst, src...)
	xorKeyStreamInPlaceBackend(dst[oldLen:], iv, rkeys)
	return dst
}

func xorSliceBlock(dst []byte, block *[BlockSize]byte) {
	dst[0] ^= block[0]
	dst[1] ^= block[1]
	dst[2] ^= block[2]
	dst[3] ^= block[3]
	dst[4] ^= block[4]
	dst[5] ^= block[5]
	dst[6] ^= block[6]
	dst[7] ^= block[7]
	dst[8] ^= block[8]
	dst[9] ^= block[9]
	dst[10] ^= block[10]
	dst[11] ^= block[11]
	dst[12] ^= block[12]
	dst[13] ^= block[13]
	dst[14] ^= block[14]
	dst[15] ^= block[15]
}

func putCounterBlock(counterBlock *[BlockSize]byte, iv uint64) {
	putCounterHead(counterBlock, iv)
	copy(counterBlock[8:16], counterBlock[0:8])
}

func putCounterHead(counterBlock *[BlockSize]byte, iv uint64) {
	counterBlock[0] = uint8(iv >> 56)
	counterBlock[1] = uint8(iv >> 48)
	counterBlock[2] = uint8(iv >> 40)
	counterBlock[3] = uint8(iv >> 32)
	counterBlock[4] = uint8(iv >> 24)
	counterBlock[5] = uint8(iv >> 16)
	counterBlock[6] = uint8(iv >> 8)
	counterBlock[7] = uint8(iv)
}

func initCipherTables() {
	cipherInitOnce.Do(initCipher)
}

func initCipher() {
	var i, j, k int
	var x [16]uint8

	for i = 0; i < 16; i++ { // 16 bytes.
		for j = 0; j < 256; j++ { // 256 possible values of bytes - used as index.

			for k = range x {
				x[k] = 0
			}
			x[i] = piTable[j]
			x = linear(x)
			// This is LS lookup table, indexed by byte values.
			// LS transformation (S, then L) as used in encryption.
			lsEncLookup[i][j] = x
			lsEncLookup64[i][j] = makeLookupBlock64(&x)

			for k = range x {
				x[k] = 0
			}
			x[i] = uint8(j)
			x = linearInv(x)
			// Inverse L lookup.
			lInvLookup[i][j] = x
			lInvLookup64[i][j] = makeLookupBlock64(&x)

			for k = range x {
				x[k] = 0
			}
			x[i] = piInverseTable[j]
			x = linearInv(x)
			// SL-inverse transformation as used in decryption.
			slDecLookup[i][j] = x
			slDecLookup64[i][j] = makeLookupBlock64(&x)

		}
	}
}

func makeLookupBlock64(block *[16]byte) lookupBlock64 {
	return lookupBlock64{
		lo: binary.LittleEndian.Uint64(block[0:8]),
		hi: binary.LittleEndian.Uint64(block[8:16]),
	}
}

type keySizeError int

func (k keySizeError) Error() string {
	return "Kuznyechik cipher: invalid key size! Must be 32 bytes!"
}
